-- ==============================================================
-- QMS PERTAMINA PATRA NIAGA RU II DUMAI
-- Microsoft SQL Server Initialization Script
-- Database: db_qms
-- ==============================================================

IF NOT EXISTS (SELECT * FROM sys.databases WHERE name = 'db_qms')
BEGIN
    CREATE DATABASE db_qms;
END
GO

USE db_qms;
GO

IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = 'tb_upload')
BEGIN
    CREATE TABLE tb_upload (
        upload_id INT PRIMARY KEY,
        menu_id INT NOT NULL,
        creator NVARCHAR(255) NOT NULL,
        file_name NVARCHAR(500) NOT NULL,
        file_dir NVARCHAR(500) NOT NULL,
        size NVARCHAR(100) NOT NULL,
        type NVARCHAR(100) NOT NULL
    );
END
GO

IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = 'tb_menu')
BEGIN
    CREATE TABLE tb_menu (
        menu_id INT PRIMARY KEY,
        menu NVARCHAR(255) NOT NULL,
        submenu NVARCHAR(255) NOT NULL
    );
END
GO

IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = 'tb_employee')
BEGIN
    CREATE TABLE tb_employee (
        no_peg INT PRIMARY KEY,
        emp_name NVARCHAR(255) NOT NULL,
        password NVARCHAR(255) NOT NULL,
        reset_pswd NVARCHAR(255) NOT NULL,
        email NVARCHAR(255) NOT NULL,
        jabatan NVARCHAR(255) NULL,
        fungsi NVARCHAR(255) NULL,
        telpon NVARCHAR(100) NULL
    );
END
GO

IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = 'tb_gugus')
BEGIN
    CREATE TABLE tb_gugus (
        id_gugus INT PRIMARY KEY,
        creator NVARCHAR(255) NOT NULL,
        category_gugus NVARCHAR(255) NOT NULL,
        nama_gugus NVARCHAR(255) NOT NULL,
        title NVARCHAR(500) NOT NULL,
        telp NVARCHAR(100) NOT NULL,
        acc NVARCHAR(100) NOT NULL
    );
END
GO

IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = 'tb_user')
BEGIN
    CREATE TABLE tb_user (
        id INT PRIMARY KEY,
        username NVARCHAR(255) NOT NULL,
        password NVARCHAR(255) NOT NULL
    );
END
GO

IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = 'tb_registered_user')
BEGIN
    CREATE TABLE tb_registered_user (
        id INT IDENTITY(1,1) PRIMARY KEY,
        username NVARCHAR(255) NOT NULL,
        full_name NVARCHAR(255) NOT NULL,
        email NVARCHAR(255) NOT NULL,
        no_peg INT NOT NULL,
        jabatan NVARCHAR(255) NULL,
        fungsi NVARCHAR(255) NULL,
        phone NVARCHAR(100) NULL,
        password NVARCHAR(255) NOT NULL,
        role NVARCHAR(100) NOT NULL DEFAULT Pegawai,
        registered_at NVARCHAR(100) NOT NULL,
        photo_url NVARCHAR(MAX) NULL
    );
END
GO

-- SEED DATA: tb_menu
IF NOT EXISTS (SELECT 1 FROM tb_menu)
BEGIN
END
GO

