GO

-- SEED DATA: tb_employee (1,882 Pegawai)
IF NOT EXISTS (SELECT 1 FROM tb_employee)
BEGIN
END
GO

-- SEED DATA: tb_registered_user
IF NOT EXISTS (SELECT 1 FROM tb_registered_user)
BEGIN
    SET IDENTITY_INSERT tb_registered_user ON;
    SET IDENTITY_INSERT tb_registered_user OFF;
END
GO
